//! The same validated profile policy editor is used by Advanced and Stream.
use eframe::egui;use skylive_core::ReconnectSettings;
#[derive(Clone)]pub struct Draft{pub enabled:bool,pub delay:u32,pub attempts:u32}
impl Draft{pub fn new(s:ReconnectSettings)->Self{Self{enabled:s.enabled(),delay:s.delay_seconds(),attempts:s.max_attempts()}}pub fn settings(&self)->Result<ReconnectSettings,String>{ReconnectSettings::new(self.enabled,self.delay,self.attempts).map_err(|e|e.to_string())}pub fn unchanged(&self,s:ReconnectSettings)->bool{self.settings().is_ok_and(|v|v==s)}}
pub fn show(ui:&mut egui::Ui,draft:&mut Draft){ui.separator();ui.strong(crate::i18n::tr(ui,"Automatic Reconnect"));ui.checkbox(&mut draft.enabled,crate::i18n::tr(ui,"Enable automatic reconnect")).on_hover_text(crate::i18n::tr(ui,"Retry recoverable transport loss after an established stream. Invalid settings, authentication, certificate and encoder failures stop the output."));ui.add_enabled_ui(draft.enabled,|ui|{egui::Grid::new("automatic-reconnect-policy").num_columns(2).show(ui,|ui|{let label=ui.label(crate::i18n::tr(ui,"Retry Delay (seconds)"));ui.add(egui::DragValue::new(&mut draft.delay).range(1..=30)).labelled_by(label.id).on_hover_text(crate::i18n::tr(ui,"First retry delay: 1 to 30 seconds. Failed attempts back off by 1.5 to 1.55, up to 15 minutes."));ui.end_row();let label=ui.label(crate::i18n::tr(ui,"Maximum Retries"));ui.add(egui::DragValue::new(&mut draft.attempts).range(1..=10000)).labelled_by(label.id).on_hover_text(crate::i18n::tr(ui,"Limit consecutive retry attempts to 1–10000. A successful new connection and fresh Program frame reset the outage counter."));ui.end_row();});});ui.small(crate::i18n::tr(ui,"Defaults: enabled, 2 seconds, 25 retries. Offline media is discarded; reconnection starts fresh at the current Program time. Stop cancels retries and retires their real output resources."));}
